import{_ as i,o as s,c as e,ag as p}from"./chunks/framework.rAhUSuuf.js";const k=JSON.parse('{"title":"OpenAPI 导出","description":"","frontmatter":{},"headers":[],"relativePath":"api/openapi.md","filePath":"api/openapi.md","lastUpdated":1770988428000}'),n={name:"api/openapi.md"};function l(o,a,t,d,h,c){return s(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="openapi-导出" tabindex="-1">OpenAPI 导出 <a class="header-anchor" href="#openapi-导出" aria-label="Permalink to &quot;OpenAPI 导出&quot;">​</a></h1><p>本项目支持导出标准 <strong>OpenAPI 3.x</strong> 文档，格式包含 JSON 与 YAML，可直接导入 Apifox、Postman 等 API 调试工具。 并支持在 VitePress 静态站中查看接口文档（无需依赖后端 Swagger UI）。</p><h2 id="导出命令" tabindex="-1">导出命令 <a class="header-anchor" href="#导出命令" aria-label="Permalink to &quot;导出命令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openapi:export</span></span></code></pre></div><p>导出后会生成以下文件：</p><ul><li><code>openapi/openapi.json</code></li><li><code>openapi/openapi.yaml</code></li><li><code>docs/website/public/openapi/openapi.json</code></li><li><code>docs/website/public/openapi/openapi.yaml</code></li></ul><h2 id="构建静态文档-含-openapi" tabindex="-1">构建静态文档（含 OpenAPI） <a class="header-anchor" href="#构建静态文档-含-openapi" aria-label="Permalink to &quot;构建静态文档（含 OpenAPI）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p><code>docs:build</code> 会先执行 <code>openapi:export</code>，再构建 VitePress 静态站。 构建完成后可通过 <code>/swagger/</code> 访问静态 Swagger UI 页面。</p><h2 id="导入-apifox" tabindex="-1">导入 Apifox <a class="header-anchor" href="#导入-apifox" aria-label="Permalink to &quot;导入 Apifox&quot;">​</a></h2><p>你可以通过两种方式导入：</p><ul><li>文件导入：选择 <code>openapi/openapi.json</code> 或 <code>openapi/openapi.yaml</code></li><li>URL 导入：部署后使用文档站静态地址，例如： <ul><li><code>/openapi/openapi.json</code></li><li><code>/openapi/openapi.yaml</code></li></ul></li></ul><h2 id="生产环境建议" tabindex="-1">生产环境建议 <a class="header-anchor" href="#生产环境建议" aria-label="Permalink to &quot;生产环境建议&quot;">​</a></h2><ul><li>生产环境可关闭后端 Swagger UI： <ul><li><code>SWAGGER_ENABLED=false</code></li></ul></li><li>文档直接使用 VitePress 静态产物部署，不依赖后端 Swagger 页面。</li><li>若仅需静态文档，可不暴露 <code>/api/v1/docs</code> 路由。</li></ul><h2 id="相关命令" tabindex="-1">相关命令 <a class="header-anchor" href="#相关命令" aria-label="Permalink to &quot;相关命令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 构建后端</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 导出 OpenAPI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openapi:export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 构建静态文档站（自动导出 OpenAPI）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 仅构建 VitePress（不重新导出 OpenAPI）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build:raw</span></span></code></pre></div>`,16)])])}const u=i(n,[["render",l]]);export{k as __pageData,u as default};
